exercises.solution:
fn make_adder() -> impl FnMut(i32) -> i32 {
    let mut sum = 0;
    move |x: i32| {
        sum += x;
        sum
    }
}

fn main() {
    let mut adder = make_adder();
    println!("{}", adder(5));
    println!("{}", adder(10));
}
